head.script:
scwin.checkVal = function() {
    return chkRefCombCust1.isOpen == false;
}
scwin.unitTest = function() {
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('chkRefCombCust1').click();");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('chkRefCombCust2').click();");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('chkRefCombCust1').click();");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('wq_uuid_7').click();");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.obj = new Object();
    obj.init = function() {
        dc_cust_ref_1.removeAll();
        dc_cust_ref_1.setJSON([{
            "MBR_NM": "일반수퍼",
            "MBR_ID": "0000005402_1000_10_10"
        }, {
            "MBR_NM": "분유",
            "MBR_ID": "0000005403_1000_10_10"
        }, {
            "MBR_NM": "도매특수",
            "MBR_ID": "0000005404_1000_10_10"
        }, {
            "MBR_NM": "학교급식",
            "MBR_ID": "0000010543_1000_10_10"
        }]);
    };
    obj.init();
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
